  add('air','basic','空気を入れたボールの空気をぬくとボールの重さは、どうなりますか。','軽くなる',['重くなる','かわらない','なくなる'],['空気には重さがありました。','空気をぬくとその分の重さは、どうなりますか。'],'空気をぬくと空気の重さの分だけ、ボールは軽くなります。',null,['軽くなる','かるくなる']);
  add('air','basic','ふくろに空気をつめて、口をとじ手でおすとどう感じますか。','おし返される',['何も感じない','引っぱられる','熱く感じる'],['ふくろの中の空気は、おしちぢめられます。','空気にはもとにもどろうとする力があります。'],'ふくろの中の空気をおしちぢめると空気がおし返してきます。',null,['おし返される','おしかえされる','押し返される']);
  add('air','basic','注射器にとじこめた空気をピストンでおして、手をはなすとピストンはどうなりますか。','もとの位置にもどる',['そのままとまる','もっとおされる','外れる'],['おしちぢめられた空気は、もとにもどろうとします。','手ごたえを思い出しましょう。'],'手をはなすと空気がもとの大きさにもどろうとして、ピストンもおしもどされます。',{"kind":"apparatus","panels":[{"tool":"syringe","contents":"air","pressed":true}],"caption":"空気をおしちぢめたときのようす","study":true});
  add('air','basic','もののかさ（場所をしめる大きさ）のことを何といいますか。','体積',['重さ','温度','長さ'],['ものが場所をどれだけしめるかを表します。','ml や cm³ で表します。'],'ものが場所をしめる大きさを体積といいます。',null,['体積','たいせき']);

