  add('air','advanced','注射器に空気50mL と水50mL を入れて、ピストンをおしました。水の体積は何mLのままですか。',50,[40,25,100],['水はおしても、体積がほとんどかわりません。','空気が縮みます。'],'水はおしても体積がほとんどかわらないので、50mLのままです。');
  add('air','advanced','密閉した注射器の中に風船を入れて、ピストンをおすと風船はどうなりますか。','小さくなる',['大きくなる','かわらない','われる'],['風船の外の空気がおしちぢめられます。','外の空気の力が風船をおします。'],'注射器の中の空気がおしちぢめられると外から風船をおす力が大きくなり、風船は小さくなります。',{"kind":"apparatus","panels":[{"tool":"syringe","contents":"balloon"}],"caption":"おす前の注射器と風船","study":true},['小さくなる','ちいさくなる','ちぢむ','縮む']);
  add('air','advanced','空気がおしちぢめられると体積が小さくなるのは、空気をどのようなものとして考えられるからですか。','空気はものの間にすきまがあり、ちぢむことができるから',['空気は固体だから','空気は水と同じだから','空気は重いだけだから'],['水はおしても体積があまりかわりません。','空気は気体です。'],'空気（気体）はものの間にすきまがあり、おすと小さくなることができます。');
  add('air','advanced','空のペットボトルのふたを閉めて、ピストンをおしこむように、おすとペットボトルはどうなりますか。','へこむ（形がかわる）',['かわらない','大きくなる','われる'],['ペットボトルの中の空気は、おしちぢめられます。','おす力が強いとき、どうなりますか。'],'ペットボトルの中の空気がおしちぢめられるので、ペットボトルはへこみます。');
  add('air','advanced','空気を入れた風船を強くおすとわれることがあります。この理由として、正しいものはどれですか。','おしちぢめられた空気がおし返す力が強くなるから',['空気がなくなるから','空気がかるくなるから','風船があたたまるから'],['空気はおしちぢめられるとおし返す力が大きくなります。','その力が風船のゴムの強さをこえたときです。'],'おしちぢめられた空気のおし返す力が、風船のゴムの強さをこえると、風船はわれます。');
  add('air','advanced','注射器に空気を100mL とじこめて、ピストンをおして、体積が半分になったとき、おし返す力ははじめと比べてどうなりますか。','大きくなる',['小さくなる','かわらない','なくなる'],['体積が小さいほど、おし返す力はどうなりますか。','強くおしたときの手ごたえを思い出しましょう。'],'体積が小さくなるほど、空気がおし返す力は大きくなります。',null,['大きくなる','おおきくなる']);
  add('air','advanced','注射器に水をいっぱい入れて、先をふさいでピストンをおしました。ピストンはどうなりますか。','ほとんど動かない',['すぐに奥までおせる','もとにもどってくる','水がふえる'],['水はおしちぢめにくいです。','空気がないときは、どうなりますか。'],'水はほとんどおしちぢめられないので、ピストンはほとんど動きません。');
  add('air','advanced','注射器のピストンを強くおしても、ほとんど動きませんでした。注射器の中に入っているのは、空気と水のどちらだと考えられますか。','水',['空気','どちらも考えられない','空気と水の両方'],['もとにもどる力は、空気にあります。','水はおしちぢめても、もどる力がありません。'],'空気はおしちぢめられますが水はおしちぢめられないので、ピストンがほとんど動かないときは、水が入っていると考えられます。',null,['水','みず']);
  add('air','advanced','暑い日にふたを閉めたペットボトルを、日なたに置いておくと、ふくらむことがあります。これは中の空気がどうなったからですか。','あたためられて、体積が大きくなったから',['冷やされて、体積が小さくなったから','入れかわったから','重くなったから'],['空気はあたためるとどうなりますか。','体積の変化を考えます。'],'空気はあたためられると体積が大きくなります。ペットボトルの中の空気が体積を大きくして、ペットボトルがふくらみます。');
  add('air','advanced','空気の重さを調べるために、ボールの空気をぬいたり入れたりして、重さを比べます。重さを調べるのに使うものは、何ですか。','はかり',['温度計','ものさし','ルーペ'],['重さを調べる道具です。','上皿てんびんも使えます。'],'重さを調べるときは、はかり（上皿てんびん）を使います。',null,['はかり','秤','上皿てんびん','うわざらてんびん']);

  // ---- 水のすがた：基礎7・標準13・発展11（原作の5問を合わせて 9/15/12）----
  add('water','basic','水がすがたをかえて、目に見えない気体になったものを何といいますか。','水蒸気',['湯気','氷','雲'],['水を熱し続けると水はすがたをかえます。','湯気は目に見えるもので、水蒸気ではありません。'],'水が気体になったものを水蒸気（すいじょうき）といいます。水蒸気は目に見えません。',null,['水蒸気','すいじょうき']);
  add('water','basic','やかんの口から出る、白いけむりのようなものを何といいますか。','湯気',['水蒸気','氷','けむり'],['水蒸気は目に見えません。','白く見えるものは、小さな水のつぶです。'],'湯気は水蒸気が冷やされて、小さな水のつぶになったものです。目に見えます。',{"kind":"scienceScene","scene":"kettle","caption":"やかんの口から出ている白いもの","study":true},['湯気','ゆげ']);
  add('water','basic','水が氷になることを何といいますか。','こおる',['とける','蒸発する','ふっとうする'],['０℃より冷やすとどうなりますか。','氷が水になるのは、「とける」です。'],'水が冷やされて氷になることをこおるといいます。',null,['こおる','凍る','氷る']);
  add('water','basic','氷が水になることを何といいますか。','とける',['こおる','蒸発する','ふっとうする'],['氷をあたためるとどうなりますか。','水が氷になるのは、「こおる」です。'],'氷が水になることをとけるといいます。',null,['とける','溶ける','解ける']);
  add('water','basic','水が水面からゆっくりと水蒸気になって、空気中へ出ていくことを何といいますか。','蒸発',['ふっとう','こおる','とける'],['水たまりがいつのまにかなくなります。','100℃より低い温度でも、起こります。'],'水が水面から水蒸気になって、空気中へ出ていくことを蒸発（じょうはつ）といいます。',null,['蒸発','じょうはつ']);
  add('water','basic','冷たい飲みものを入れたコップの外側に水てきがつきました。この水はどこから出てきたものですか。','空気中の水蒸気',['コップの中の飲みもの','コップの水','氷がとけたもの'],['コップの外側は、冷やされています。','空気中には水蒸気があります。'],'空気中の水蒸気が冷たいコップにふれて冷やされ、水になって、水てきがつきました。',{"kind":"scienceScene","scene":"coldCup","caption":"冷たい飲みものと、コップの外の水てき","study":true});
  add('water','basic','水の３つのすがたは、固体・液体とあと１つは何ですか。','気体',['湯気','雲','水蒸気ガス'],['氷は固体、水は液体です。','水蒸気は気体です。'],'水は固体（氷）・液体（水）・気体（水蒸気）の、３つのすがたにかわります。',null,['気体','きたい']);

  add('water','standard','水を熱し続けて、ふっとうしている間水の温度はどうなりますか。','かわらない（約100℃のまま）',['どんどん上がる','下がる','ゆっくり上がる'],['ふっとうしている間の温度を思い出しましょう。','水がふっとうする温度は、およそ100℃です。'],'ふっとうしている間、水の温度は約100℃のままでかわりません。');
  add('water','standard','氷がとけている間、温度は何℃のままですか。',0,[10,50,100],['氷がとけて水になる温度です。','水がこおる温度と同じです。'],'氷がとけている間は、温度は０℃のままです。');
  add('water','standard','100gの氷がとけて水になりました。水の重さはおよそ何gですか。',100,[50,90,200],['すがたがかわっても、ものの量はかわりません。','重さはかわるでしょうか。'],'氷がとけて水になっても、ものの量はかわらないので、重さは100gのままです。');
  add('water','standard','水が水蒸気になると体積はどうなりますか。','とても大きくなる',['小さくなる','かわらない','なくなる'],['湯気が出ているとき、やかんの中の水はへっています。','気体になるとすきまが広がります。'],'水が水蒸気になると体積はとても大きくなります。');
  add('water','standard','冬の朝、まどガラスの内側がくもりました。これは空気中の水蒸気がどうなったからですか。','冷やされて、水のつぶになったから',['あたためられて、水蒸気になったから','氷になったから','ガラスから出てきたから'],['まどガラスは外の冷たい空気で冷やされています。','水蒸気は冷やされるとどうなりますか。'],'部屋の中の水蒸気が冷たいまどガラスにふれて冷やされ、小さな水のつぶになって、くもります。',{"kind":"scienceScene","scene":"window","caption":"冬の朝の、まどの内側","study":true});
  add('water','standard','水を入れた容器にふたをしないで、日なたに置いておくと、水はどうなりますか。','少しずつへる',['かわらない','ふえる','こおる'],['水は水面からゆっくりすがたをかえます。','そのことを何といいましたか。'],'水が水面から蒸発して、少しずつへっていきます。');
  add('water','standard','水を熱して、あわが出てきました。このあわの正体は、何ですか。','水蒸気',['空気','湯気','氷'],['水が熱せられて、すがたをかえています。','水の中から出てきた気体です。'],'ふっとうしているときの、あわの正体は、水が水蒸気になったものです。',null,['水蒸気','すいじょうき']);
  add('water','standard','氷に食塩を混ぜると温度はどうなりますか。','０℃より低くなる',['０℃より高くなる','０℃のままかわらない','100℃になる'],['氷と食塩を混ぜたとき、温度計で調べる実験があります。','氷に食塩を混ぜるととても冷たくなります。'],'氷に食塩を混ぜると０℃より低い温度になります。');
  add('water','standard','水を熱して、ふっとうしてからさらに熱し続けると水の量はどうなりますか。','へる',['ふえる','かわらない','全部氷になる'],['ふっとうしている水は、水蒸気になっていきます。','水蒸気は空気中に出ていきます。'],'ふっとうしている間、水はどんどん水蒸気になるので、水の量はへります。',null,['へる','減る','少なくなる']);
  add('water','standard','洗たくものがかわくのは水がどうなるからですか。','水蒸気になって、空気中へ出ていくから',['水が氷になるから','水が布にしみこむから','水がふっとうするから'],['洗たくものの水は、空気中へ出ていきます。','水が水蒸気になることを何といいましたか。'],'洗たくものの水は、蒸発して水蒸気になり空気中へ出ていきます。そのため、かわきます。');
  add('water','standard','水を冷やして氷にすると、体積はどうなりますか。','大きくなる',['小さくなる','かわらない','なくなる'],['ペットボトルに水を入れて、冷凍庫に入れるとどうなりますか。','氷は水にうきます。'],'水が氷になると体積は大きくなります。そのため、氷は水にうきます。',null,['大きくなる','ふえる','増える']);
  add('water','standard','氷が水にういているのは、同じ重さで比べたとき、氷の体積が水よりどうだからですか。','大きいから',['小さいから','かわらないから','重いから'],['同じ重さなら、体積が大きいほうがかるいといえます。','氷の体積は水が氷になるとどうなりますか。'],'同じ重さで氷のほうが体積が大きいので、水にうきます。',null,['大きい','おおきい']);
  add('water','standard','ふっとうしているやかんの口の、すぐそばには湯気が見えません。これは口のすぐそばは、何だからですか。','水蒸気で、目に見えないから',['氷で、目に見えないから','空気で、何もないから','熱くて、湯気が消えるから'],['やかんの中から出てくるのは、水蒸気です。','湯気は水蒸気が冷やされたものです。'],'やかんの口のすぐそばは水蒸気のままで目に見えません。少しはなれて冷やされると小さな水のつぶになり、湯気として見えます。');

  add('water','advanced','ビーカーの水を熱して、ふっとうしたあと、ビーカーの上に冷たいガラス板をかぶせました。ガラス板の内側には、何がつきますか。','水てき',['氷','水蒸気','あわ'],['ふっとうして出た水蒸気は、ガラス板で冷やされます。','冷やされた水蒸気は、どうなりますか。'],'水蒸気が冷たいガラス板で冷やされて、水になるため、水てきがつきます。',{"kind":"apparatus","panels":[{"tool":"beaker","heat":true,"boiling":true,"lid":"glass","notes":["冷たいガラス板"]}],"caption":"ビーカーとガラス板。板につくものは示していない","study":true},['水てき','水滴','すいてき']);
  add('water','advanced','水を熱して、温度をはかり続けたとき、ふっとうしてからずっと温度がかわらないのは、加えられた熱が何に使われるからですか。','水を水蒸気にかえることに使われるから',['水を氷にかえることに使われるから','空気をあたためることだけに使われるから','何にも使われないから'],['ふっとうしている間、水はすがたをかえています。','温度がかわらなくても、水はへっています。'],'ふっとうしている間は、加えた熱が水が水蒸気にかわることに使われるので、温度は上がりません。');
  add('water','advanced','ふっとうしていなくても、水が水蒸気になることを何といいますか。','蒸発',['ふっとう','とける','こおる'],['水たまりがなくなる、洗たくものがかわくなどの場面です。','100℃より低くても、起こります。'],'ふっとうしていなくても、水が水面から水蒸気になることを蒸発といいます。',null,['蒸発','じょうはつ']);
  add('water','advanced','日なたと日かげに、同じ量の水を入れた容器を置いておきました。水が早くへるのは、どちらですか。','日なた',['日かげ','どちらも同じ','どちらもへらない'],['温度が高いほど、蒸発しやすいです。','日なたの水はあたためられます。'],'日なたは温度が高くなるので、水が蒸発しやすく早くへります。',null,['日なた','ひなた']);
  add('water','advanced','水を入れたビーカーにふたをして、あたためるとふたの内側がくもりました。ビーカーの中の水蒸気は、どうなりましたか。','ふたで冷やされて、水になった',['氷になった','なくなった','空気になった'],['水は蒸発して、水蒸気になります。','水蒸気は冷やされるとどうなりますか。'],'水が蒸発してできた水蒸気が冷たいふたにふれて冷やされ、水てきになって、ふたの内側にくっつきます。',{"kind":"apparatus","panels":[{"tool":"beaker","heat":true,"lid":"cover"}],"caption":"ふたをしたビーカーをあたためるようす","study":true});
  add('water','advanced','氷水（氷を入れた水）の中に温度計を入れて、そのまま置いておくと氷が少しとけてきました。そのとき、水の温度はおよそ何℃ですか。',0,[10,5,100],['氷がとけている間の温度は、かわりません。','氷がとけはじめる温度です。'],'氷が水にとけている間は、温度はおよそ０℃のままです。',{"kind":"apparatus","panels":[{"tool":"beaker","ice":true,"therm":true}],"caption":"氷水に入れた温度計。目もりは示していない","study":true});
  add('water','advanced','100℃より高い温度で水のすがたは何ですか。','気体（水蒸気）',['液体','固体','氷'],['水がふっとうする温度は、約100℃です。','ふっとう点より高いと水はどうなりますか。'],'100℃をこえると水は水蒸気（気体）になります。');
  add('water','advanced','水をふっとうさせるとき、ふっとう石を入れるのはどうしてですか。','急にふっとうして、湯がとびはねるのを防ぐため',['水を冷やすため','水の重さをはかるため','水をにごらせるため'],['ふっとうするとき、急にあわが出てあぶないことがあります。','ガラス器具を使うときに起こることです。'],'ふっとう石は湯が急にふっとうして、とびはねるのを防ぎます。');
  add('water','advanced','水を熱してふっとうさせたら、あわがブクブクと出ました。そのあわをつめたいビニールぶくろで、おおうと、ふくろの内側に何がつきましたか。','水てき',['氷','空気','何もつかない'],['あわは水がすがたをかえたものでした。','水蒸気は冷やされるとどうなりますか。'],'あわの正体の水蒸気が冷たいふくろで冷やされて、水になりました。',null,['水てき','水滴','すいてき']);
  add('water','advanced','水が水蒸気になって空気中に出ていくこと水蒸気が水にもどること水が氷になることのうち、「熱をうばわれる」ことで起こるのは、どれですか。','水蒸気が水になること水が氷になること',['水が水蒸気になること','氷が水になること','どれも熱を加えたときに起こる'],['水蒸気が水に水が氷になるときはどうなりますか。','冷やされるときに起こることを選びます。'],'水蒸気が水になる水が氷になる、は冷やされるときに起こります。水が水蒸気になる氷が水になる、は熱を加えたときに起こります。');
  add('water','advanced','水・氷・水蒸気を体積の大きい順にならべたとき、正しいものはどれですか。（同じ重さで比べます）','水蒸気、氷、水',['氷、水、水蒸気','水、氷、水蒸気','水蒸気、水、氷'],['水蒸気の体積は、とても大きいです。','氷は水にうきます。'],'同じ重さで比べると水蒸気がもっとも大きく次が氷、いちばん小さいのが水です。');

