  add('heat','basic','温度計で温度をはかるとき、目もりはどの向きから読みますか。','真横から',['真上から','真下から','ななめ上から'],['目の高さを液面と同じにします。','ななめから見ると読みちがえます。'],'温度計の目もりは、液の先と目の高さを同じにして、真横から読みます。',{"kind":"apparatus","panels":[{"tool":"thermometer","eyes":true}],"caption":"目もりを見る、３つの目の位置","study":true},['真横','まよこ','真横から','まよこから']);
  add('heat','basic','温度計の液だめ（下の丸い部分）に手でふれてはいけない理由は、何ですか。','手の温度がつたわってしまうから',['温度計がこわれるから','目もりが消えるから','液だめがよごれるから'],['液だめに手がふれると手の温度がつたわります。','正しい温度がはかれなくなります。'],'手の温度が液だめにつたわり、正しい温度をはかれないので、手でふれてはいけません。');
  add('heat','basic','水をあたためるとあたたまった水は、上と下のどちらへ動きますか。','上',['下','横','動かない'],['あたたまった水は、軽くなります。','あたたまり方を思い出しましょう。'],'あたためられた水は上へ動き、上のほうの冷たい水が下へ動いて、全体があたたまります。',{"kind":"apparatus","panels":[{"tool":"beaker","heat":true}],"caption":"水を下から熱するようす。水の動きは示していない","study":true},['上','うえ']);
  add('heat','basic','金属のぼうのはしを熱すると、熱はどのようにつたわりますか。','熱したところから順につたわる',['ぼう全体に同時につたわる','熱したところと反対側からつたわる','つたわらない'],['金属は熱したところからはなれるほど、おそくあたたまります。','熱が順につたわっていきます。'],'金属は熱したところから順に熱がつたわり、あたたまります。',{"kind":"apparatus","panels":[{"tool":"rod","heat":true}],"caption":"ぼうのはしを熱するようす","study":true});
  add('heat','basic','空気をあたためると空気の体積はどうなりますか。','大きくなる',['小さくなる','かわらない','なくなる'],['ふたをした試験管をあたためるとどうなりますか。','あたためると広がります。'],'空気はあたためると体積が大きくなります。',null,['大きくなる','おおきくなる','ふえる','増える']);
  add('heat','basic','空気を冷やすと空気の体積はどうなりますか。','小さくなる',['大きくなる','かわらない','なくなる'],['へこんだボールをあたためるともとにもどります。','冷やすとちぢみます。'],'空気は冷やすと体積が小さくなります。',null,['小さくなる','ちいさくなる','ちぢむ','縮む']);
  add('heat','basic','金属の球を熱すると、体積はどうなりますか。','わずかに大きくなる',['大きく小さくなる','かわらない','なくなる'],['金属も熱すると、のびます。','変化はとても小さいです。'],'金属は熱すると体積がわずかに大きくなります。',null,['大きくなる','わずかに大きくなる','おおきくなる']);
  add('heat','basic','ガラスのくだに水を入れて熱すると、水面はどうなりますか。','上がる',['下がる','かわらない','なくなる'],['水をあたためると体積はどうなりますか。','体積が大きくなると水面が上がります。'],'水はあたためると体積が大きくなるので、水面が上がります。',{"kind":"apparatus","panels":[{"tool":"flask","heat":true}],"caption":"水とガラスのくだ。水面の変化は示していない","study":true},['上がる','あがる']);

  add('heat','standard','金属・水・空気を同じようにあたためたとき、体積がいちばん大きくふえるのは、何ですか。','空気',['金属','水','どれも同じ'],['体積の変化が大きいのは、気体です。','金属はわずかにふえます。'],'あたためたとき、体積の変化は空気がもっとも大きく次が水、金属の変化がもっとも小さいです。',null,['空気','くうき']);
  add('heat','standard','金属・水・空気を冷やしたとき、体積の変化がいちばん小さいのは、何ですか。','金属',['水','空気','どれも同じ'],['体積の変化が小さいのは、固体です。','空気は体積が大きく変わります。'],'冷やしたとき、体積の変化は金属がもっとも小さく次が水、空気がもっとも大きいです。',null,['金属','きんぞく']);
  add('heat','standard','金属の輪をぴったり通る金属の球があります。球だけを熱したあと、輪を通そうとするとどうなりますか。','通らなくなる',['すぐに通る','もっとかんたんに通る','かわらない'],['熱すると、金属の体積はどうなりますか。','球がわずかに大きくなります。'],'球を熱すると、体積がわずかに大きくなるので、輪を通らなくなります。',{"kind":"apparatus","panels":[{"tool":"ballRing","heat":true}],"caption":"球を熱するようす。輪は球と別に置いている","study":true},['通らなくなる','とおらなくなる','通らない','とおらない']);
  add('heat','standard','熱した金属の球を冷やしたら、また輪を通るようになりました。これは球の体積がどうなったからですか。','小さくなって、もとにもどったから',['大きくなったから','かわらなかったから','なくなったから'],['熱すると、大きくなりました。','冷やすとどうなりますか。'],'冷やすと体積が小さくなってもとにもどったので、輪を通れるようになりました。');
  add('heat','standard','へこんだピンポン玉を、お湯に入れると、もとにもどることがあります。これは中の空気がどうなったからですか。','あたためられて、体積が大きくなったから',['冷やされたから','なくなったから','重くなったから'],['空気はあたためられると体積が大きくなります。','ピンポン玉の中の空気がおし出します。'],'ピンポン玉の中の空気がお湯であたためられて体積が大きくなり、へこみをおし出して、もとにもどります。');
  add('heat','standard','ふたをした試験管の口にせっけん水のまくをはって、試験管をお湯の中に入れました。まくはどうなりますか。','ふくらむ',['へこむ','かわらない','われる'],['試験管の中の空気は、あたためられます。','空気の体積はどうなりますか。'],'試験管の中の空気があたためられて、体積が大きくなりまくをおし上げるので、ふくらみます。',{"kind":"apparatus","panels":[{"tool":"tubeBath","bath":"hot","membrane":"flat"}],"caption":"試験管を水に入れるようす。まくは平ら","study":true},['ふくらむ']);
  add('heat','standard','ふたをした試験管の口にせっけん水のまくをはって、試験管を氷水の中に入れました。まくはどうなりますか。','へこむ',['ふくらむ','かわらない','われる'],['試験管の中の空気は、冷やされます。','冷やすと空気の体積はどうなりますか。'],'試験管の中の空気が冷やされて、体積が小さくなり、まくがへこみます。',{"kind":"apparatus","panels":[{"tool":"tubeBath","bath":"ice","membrane":"flat"}],"caption":"試験管を水に入れるようす。まくは平ら","study":true},['へこむ']);
  add('heat','standard','水を入れたビーカーを下から熱します。水はどのようにあたたまりますか。','あたたまった水が上へ動いて、全体があたたまる',['熱した所だけがあたたまる','上のほうだけがあたたまる','下のほうだけがあたたまる'],['あたためられた水は、軽くなります。','水が動いてあたたまります。'],'あたためられた水が上へ動き、上の冷たい水が下へ動くことをくり返して、全体があたたまります。',{"kind":"apparatus","panels":[{"tool":"beaker","heat":true}],"caption":"水を下から熱するようす。水の動きは示していない","study":true});
  add('heat','standard','部屋をストーブであたためるとあたたかい空気は、どこに集まりますか。','部屋の上のほう',['部屋の下のほう','部屋の真ん中だけ','かべのそば'],['あたためられた空気は、軽くなります。','水のあたたまり方と同じです。'],'あたためられた空気は軽くなって上へ動くので、部屋の上のほうにあたたかい空気が集まります。',null,['上のほう','うえのほう','上','うえ']);
  add('heat','standard','エアコンで部屋をあたためるとき、あたたかい風は、どの向きに出すとよいですか。','下向き',['上向き','横向き','どの向きでも同じ'],['あたたかい空気は、上へ動きます。','部屋の下のほうをあたためたいときは、どうしますか。'],'あたたかい空気は上へ動くので、暖房のときは風を下向きに出すと部屋全体があたたまりやすいです。',null,['下向き','したむき','下','した']);
  add('heat','standard','かん詰のふたをあたためて、開けやすくするとき、ふたの金属はどうなりますか。','体積が大きくなって、ゆるむ',['体積が小さくなる','かわらない','かたくなる'],['金属は熱すると、どうなりますか。','ふたがびんの口より大きくなります。'],'金属のふたを熱すると、体積がわずかに大きくなってゆるむので、開けやすくなります。');
  add('heat','standard','ふっとうしているお湯の温度は、およそ何℃ですか。',100,[50,80,200],['水がふっとうする温度を思い出しましょう。','水蒸気になる温度です。'],'ふっとうしているお湯の温度は、およそ100℃です。');
  add('heat','standard','水を熱し始める前の温度は20℃でした。熱し始めて５分後に40℃になりました。ふっとうするまで同じ割合で上がるとして、10分後は何℃ですか。',60,[50,80,100],['５分ごとに何℃ずつ上がっていますか。','20℃上がるのに、５分かかっています。'],'５分で20℃ずつ上がるので、10分後は 20＋20＋20＝60℃です。');

  add('heat','advanced','温度計をお湯につけて、目もりを読みました。液面がちょうど「45」のところにありました。温度は何℃ですか。',45,[44,55,40],['液面と同じ目もりを読みます。','目もりは真横から読みます。'],'液面が45の目もりにあるので、温度は45℃です。',{"kind":"apparatus","panels":[{"tool":"beaker","therm":true,"scale":{"min":0,"max":100,"step":10,"value":45}}],"caption":"温度計の目もりを読もう","study":true});
  add('heat','advanced','金属の板のはしを熱したとき、熱したところから遠いところまで熱がつたわるといえるのは何のはたらきですか。','熱が金属の中を順につたわっていくこと',['金属が動いて、熱をはこぶこと','熱が空気を通って、つたわること','金属があたたまると軽くなること'],['金属は熱したところから順にあたたまります。','金属が動くわけではありません。'],'金属は熱したところから順に熱がつたわっていきます。',{"kind":"apparatus","panels":[{"tool":"plate","heat":true}],"caption":"板のはしを熱するようす","study":true});
  add('heat','advanced','水があたためられると動くようすを調べるために、ビーカーの水に何を入れると水の動きがわかりやすくなりますか。','みそやおがくずなどの小さなつぶ',['砂糖','食塩','氷'],['水の動きを目で見えるようにしたいのです。','水といっしょに動く小さなつぶです。'],'みそなどの小さなつぶを入れると水といっしょに動くので、水の動きが見えます。');
  add('heat','advanced','ふたをした試験管の口にせっけん水のまくをはって、手でにぎったら、まくがふくらみました。これは手の何が試験管の中の空気につたわったからですか。','熱',['光','音','力'],['手はあたたかいです。','空気の体積が大きくなりました。'],'手の熱が試験管の中の空気につたわって、あたためられ体積が大きくなって、まくがふくらみます。',null,['熱','ねつ']);
  add('heat','advanced','とけないぴったりしまったびんのふたを、お湯につけると、あけやすくなることがあります。これはふたが何になるためですか。','体積が大きくなるため',['体積が小さくなるため','軽くなるため','かたくなるため'],['金属は熱すると、どうなりますか。','お湯は熱いです。'],'金属のふたがお湯であたためられて体積がわずかに大きくなり、ゆるんであけやすくなります。');
  add('heat','advanced','同じ量の水・空気・金属を同じ温度だけあたためたとき、体積の変化の大きさを大きい順にならべたものは、どれですか。','空気、水、金属',['金属、水、空気','水、空気、金属','空気、金属、水'],['もっとも変化が大きいのは、気体です。','もっとも変化が小さいのは、固体です。'],'体積の変化は空気（気体）、水（液体）、金属（固体）の順に大きいです。');
  add('heat','advanced','金属の線路は夏と冬でつなぎ目にすきまがあけてあります。これは金属がどうなるからですか。','夏にのびて、冬にちぢむから',['夏にちぢんで、冬にのびるから','ずっと同じ長さだから','何もかわらないから'],['金属は熱すると、体積が大きくなります。','夏と冬の温度のちがいを考えます。'],'金属は暑い夏にはのびて、寒い冬にはちぢむので、つなぎ目にすきまがあけてあります。');
  add('heat','advanced','水をビーカーの底の中心でなくはしを熱したとき、水はどのように動きますか。','熱したほうが上がり、反対側が下がる',['熱したほうが下がる','動かない','全体が上へ動く'],['熱せられた水は、軽くなって上へ動きます。','水はまわるように動きます。'],'熱せられた水は上へ動き、反対側で冷たい水が下へ動いて、水がぐるぐると回るように動きます。',{"kind":"apparatus","panels":[{"tool":"beaker","heat":true,"edgeHeat":true}],"caption":"ビーカーのはしを熱するようす","study":true});
  add('heat','advanced','お湯にふくろを入れて、口をしばって水で冷やしました。ふくろはどうなりますか。','ふくろがへこむ',['ふくらむ','かわらない','われる'],['ふくろの中の空気は、冷やされます。','冷やされた空気の体積は、どうなりますか。'],'ふくろの中の空気が冷やされて体積が小さくなるので、ふくろはへこみます。',{"kind":"apparatus","panels":[{"tool":"bagBath","bath":"hot"}],"caption":"水と口をしばったふくろ。変化は示していない","study":true});
  add('heat','advanced','金属のぼうを熱し続けると熱したところから、はなれた場所に、だんだん熱がつたわります。この熱のつたわり方を調べるために、ぼうに何をぬっておくとよいですか。','熱で色がかわるもの（温度で色がかわるインク）',['水','油','砂'],['熱がつたわったところが見えるようにします。','温度で、色がかわるものがあります。'],'温度で色がかわるものをぬっておくと、熱がつたわったところが、色の変化で見えます。');
  add('heat','advanced','ストーブの前の空気は、あたためられると軽くなります。この空気はどのように動きますか。','上へ動く',['下へ動く','動かない','横へしか動かない'],['あたためられた水は、上へ動きました。','空気も同じです。'],'あたためられた空気は軽くなるので、上へ動きます。',{"kind":"scienceScene","scene":"room","caption":"ストーブのある部屋。空気の動きは示していない","study":true},['上へ動く','うえへうごく','上','うえ']);

  // ---- 季節と生き物：基礎8・標準14・発展12（原作の2問を合わせて 9/15/12）----
  add('season','basic','サクラの花がさく季節は、いつですか。','春',['夏','秋','冬'],['気温がだんだん高くなる季節です。','入学式のころを思い出しましょう。'],'サクラの花は春にさきます。',null,['春','はる']);
  add('season','basic','夏に気温が高くなるとヘチマのくきや葉は、どうなりますか。','どんどんのびて、よくしげる',['かれる','ちぢむ','かわらない'],['夏は植物がよく育つ季節です。','気温が高いと植物の成長はどうなりますか。'],'夏は気温が高いので、ヘチマのくきはどんどんのびて、葉もよくしげります。');
  add('season','basic','木の葉が赤や黄色にかわる季節は、いつですか。','秋',['春','夏','冬'],['木の葉が落ちる前の季節です。','気温がだんだん低くなる季節です。'],'木の葉の色が赤や黄色にかわるのは、秋です。',null,['秋','あき']);
  add('season','basic','カエルは冬のあいだ、どこですごしますか。','土の中',['水の上','木の上','空の上'],['寒さをさけて、ねむったようにすごします。','動物は冬の間はどうやってすごしますか。'],'カエルは冬のあいだ、土の中や水底でほとんど動かずにすごします（冬眠）。',null,['土の中','つちのなか','土']);
  add('season','basic','秋になるとツバメはどこへ向かいますか。','あたたかい南の国',['寒い北の国','日本の山','海の中'],['ツバメは渡り鳥です。','寒くなる前に、あたたかい所へ行きます。'],'ツバメは秋になるとあたたかい南の国へ渡っていきます。');
  add('season','basic','ヘチマのたねをまく季節はいつですか。','春',['夏','秋','冬'],['気温がだんだん高くなる季節です。','芽が出て、のびはじめるころです。'],'ヘチマのたねは、春にまきます。夏に大きく育ち、秋に実がなります。',null,['春','はる']);
  add('season','basic','動物の活動がさかんになるのは、気温が高い季節と低い季節のどちらですか。','気温が高い季節',['気温が低い季節','どちらも同じ','季節は関係ない'],['春から秋にかけて、虫や鳥をよく見かけます。','冬はどうなっていましたか。'],'気温が高い春から秋は、動物の活動がさかんです。冬はあまり見かけなくなります。',null,['気温が高い季節','気温が高い','春から秋','あたたかい季節']);
  add('season','basic','カマキリは冬のあいだ、どんなすがたですごしますか。','卵',['成虫','よう虫','さなぎ'],['カマキリの成虫は冬の前に、死んでしまいます。','あわのようなものの中に入っています。'],'カマキリは秋に卵をうみ、卵のすがたで冬をすごします。',null,['卵','たまご']);

  add('season','standard','冬、木のえだについている小さな芽を何といいますか。','冬芽',['春芽','秋芽','夏芽'],['冬の間にえだにできています。','春になると葉や花になります。'],'冬のえだについている芽を冬芽（ふゆめ）といいます。春になると葉や花になります。',{"kind":"scienceScene","scene":"branch","caption":"葉のないえだと、小さな芽","study":true},['冬芽','ふゆめ']);
  add('season','standard','ナナホシテントウは、冬のあいだどんなすがたですごしますか。','成虫',['卵','よう虫','さなぎ'],['落ち葉の下などに集まってすごします。','冬はえさがとれません。'],'ナナホシテントウは、成虫のすがたで落ち葉の下などで冬をすごします。',null,['成虫','せいちゅう']);
  add('season','standard','アゲハ（ナミアゲハ）は、冬のあいだどんなすがたですごしますか。','さなぎ',['卵','よう虫','成虫'],['アゲハは完全変態の虫です。','木のえだなどにくっついています。'],'アゲハはさなぎのすがたで冬をすごします。春になると成虫になって出てきます。',null,['さなぎ']);
  add('season','standard','秋にヘチマの実がじゅくしてきました。実の中にできているものは、何ですか。','たね',['花','葉','根'],['来年、芽を出すためのものです。','実の中を思い出しましょう。'],'ヘチマの実の中には、たねができます。来年の春にまた芽を出します。',null,['たね','種']);
  add('season','standard','冬、寒くなると木の葉がすっかり落ちる木があります。これを何といいますか。','落葉樹',['常緑樹','低木','草木'],['葉が落ちるのは、冬の寒さにたえるためです。','サクラやイチョウがなかまです。'],'冬に葉を落とす木を落葉樹（らくようじゅ）といいます。サクラやイチョウがなかまです。',null,['落葉樹','らくようじゅ']);
  add('season','standard','ガンやハクチョウは、冬になると日本にやってきます。このような鳥を何といいますか。','渡り鳥',['留鳥','野鳥','水鳥'],['寒い国からやってくる鳥です。','季節によって、すむ場所をかえます。'],'季節によって、すむ場所をかえる鳥を渡り鳥といいます。ガンやハクチョウは、冬に日本へ渡ってきます。',null,['渡り鳥','わたりどり']);
  add('season','standard','気温が下がる冬、動物の活動は春や夏とくらべて、どうなりますか。','少なくなる',['さかんになる','かわらない','夜だけさかんになる'],['冬はえさが少なくなります。','カエルやヘビは、冬眠します。'],'冬は気温が低くえさも少ないので、動物の活動は少なくなります。',null,['少なくなる','すくなくなる','へる','減る']);
  add('season','standard','春になって気温が高くなるとヘチマのくきは、どうなりますか。','のびはじめる',['かれる','かわらない','ちぢむ'],['気温と植物の成長の関係を考えます。','春は植物が成長を始める季節です。'],'春は気温が高くなるので、ヘチマは芽を出しくきがのびはじめます。',null,['のびはじめる','のびる','のびていく','成長する']);
  add('season','standard','気温が低くなる秋から冬にかけて、コオロギなどの虫は、どうなりますか。','死んで卵を残す',['冬眠する','冬もさかんに鳴く','葉の上で、冬をこす'],['コオロギは秋に鳴く虫です。','卵のすがたで、冬をこすものが多いです。'],'コオロギなどは、秋に卵をうみ成虫は冬の前に死んでしまいます。卵が冬をこして、春にふ化します。');
  add('season','standard','季節による生き物の様子を調べるとき、毎回、同じ場所を観察する理由は、何ですか。','変化をくらべやすいから',['見やすい場所だから','景色がきれいだから','虫が多いから'],['同じ場所で調べるとどうなりますか。','前とくらべます。'],'同じ場所を観察すると、季節による変化をくらべやすく記録も整理しやすいです。');
  add('season','standard','夏、ヘチマの花は何色ですか。','黄色',['赤','白','青'],['ヘチマはおばなとめばながさきます。','ヘチマの花は夏にさきます。'],'ヘチマの花は黄色で夏にさきます。おばなとめばなが別々にさきます。',null,['黄色','きいろ','黄']);
  add('season','standard','サクラが春に花をさかせるために、前の年の夏から秋にかけて、準備するものは何ですか。','花芽',['冬芽の葉','根','たね'],['春に花になる芽は、前の年のうちにできています。','冬にはえだについています。'],'サクラは前の年の夏から秋に花芽をつくり、冬をこして、春に花をさかせます。',null,['花芽','はなめ','かが']);
  add('season','standard','秋の終わりにヘチマのくきや葉は、どうなりますか。','かれる',['のびる','青くしげる','花がさく'],['気温が低くなると植物はどうなりますか。','夏とくらべて、気温はどうなっていますか。'],'秋の終わりから冬にかけて気温が低くなるとヘチマのくきや葉は、かれていきます。',null,['かれる','枯れる']);
  add('season','standard','秋に木の実をたべて、たくわえ冬にそなえる動物はどれですか。','リス',['カエル','ツバメ','トンボ'],['冬の食べものが少なくなる前に、集めておきます。','木の実を集める動物です。'],'リスは秋に木の実をたくわえて、冬にそなえます。');

  add('season','advanced','ヘチマのくきがのびる速さを春・夏・秋で比べるといちばん速いのは、いつですか。','夏',['春','秋','冬'],['いちばん、気温が高い季節です。','植物は気温が高いとよく育ちます。'],'ヘチマは気温が高い夏にいちばん速くのびます。',null,['夏','なつ']);
  add('season','advanced','気温が下がるとへびやカエルのような動物が冬眠するのは、どうしてですか。','体温が下がって、活動できなくなるから',['動くのがきらいだから','えさが多すぎるから','水がきらいだから'],['カエルやヘビは、まわりの温度で体の温度がかわります。','寒いと体が動かしにくくなります。'],'まわりの温度が下がると体温も下がって、動けなくなるため、冬眠します。');
  add('season','advanced','気温の高い夏にアサガオやヘチマの葉が大きく広がるのは、何をたくさんつくるためですか。','養分',['空気','熱','風'],['葉は日光を受けとって、何かをつくります。','植物が成長するために必要なものです。'],'葉は日光を受けて養分をつくります。夏は日光が強いので、葉が大きく広がり養分をたくさんつくります。',null,['養分','ようぶん']);
  add('season','advanced','春になって、気温が上がると冬ごしをしていた、さなぎはどうなりますか。','成虫になって出てくる',['よう虫にもどる','卵になる','死んでしまう'],['アゲハはさなぎで冬をこします。','さなぎの中で、体がかわっています。'],'春に気温が上がるとさなぎの中で成長が進み、成虫になって出てきます。');
  add('season','advanced','季節ごとの気温と生き物の変化を1年間記録するとき、観察カードに必ず書くべきものは、どれですか。','日付・天気・気温・様子',['見た人の名前だけ','好きな色だけ','天気だけ'],['あとでくらべるために、書くものです。','気温と生き物の関係を調べます。'],'日付・天気・気温・生き物の様子を記録すると、季節ごとの変化をくらべることができます。',{"kind":"table","head":["","","",""],"rows":[["","","",""],["","","",""],["","","",""]],"caption":"記録するための、空の観察カード","study":true});
  add('season','advanced','冬、サクラの木が葉をすべて落としているのは、どうしてだと考えられますか。','寒さにたえて、養分や水分をむだにしないため',['花をさかせるため','根が成長するため','太陽に当たりたくないため'],['冬は日光が弱く気温も低いです。','冬は植物の成長がとまります。'],'冬は日光が弱く気温も低いので、葉を落として、養分や水分をむだにしないようにしていると考えられます。');
  add('season','advanced','秋にサクラの葉が赤くなってから落ちます。この後、サクラの木は冬をどのようにすごしますか。','冬芽をつけて、冬をこす',['全部かれて、なくなる','根が冬に成長する','新しい葉が冬に出る'],['枝に冬芽がありました。','春になると芽が成長します。'],'サクラは葉を落とし、冬芽をつけて冬をこして、春に新しい芽を出します。');
  add('season','advanced','ナナホシテントウが春にあらわれ、アブラムシを食べるのは、何のためですか。','成長して、卵をうむため',['冬眠するため','巣をつくるため','渡るため'],['春から夏は動物の活動がさかんになります。','アブラムシはえさです。'],'テントウムシは、春にあたたかくなると活動をはじめ、えさをたくさん食べて成長し卵をうみます。');
  add('season','advanced','植物の1年を調べたとき、成長が止まるのはどの季節ですか。','冬',['春','夏','秋'],['気温が低い季節です。','日光も弱くなります。'],'冬は気温が低く日光も弱いので、植物の成長は止まります。',null,['冬','ふゆ']);
  add('season','advanced','動物が冬にそなえて、体にたくわえるものは何ですか。','脂肪',['水','土','空気'],['冬はえさがとれなくなります。','体にたくわえます。'],'クマやリスなどは、秋にたくさん食べて、体に脂肪をたくわえ冬にそなえます。',null,['脂肪','しぼう','あぶら']);
  add('season','advanced','夏の夜、よく鳴いていた虫が秋に鳴かなくなりました。この変化は何のせいだと考えられますか。','気温が下がったため',['雨がふったため','星が見えなくなったため','風が強くなったため'],['夏から秋にかけて、季節がかわります。','虫の活動は気温でかわります。'],'秋になって、気温が下がると虫の活動が少なくなり、鳴かなくなります。');
  add('season','advanced','季節の生き物の変化を調べる方法として、正しいものはどれですか。','同じ生き物を1年を通して、記録する',['1日だけ観察する','好きな季節だけ観察する','写真だけをとる'],['季節ごとの変化をくらべたいのです。','長い期間、観察を続けます。'],'同じ生き物を1年を通して観察し、記録すると、季節による変化がわかります。',{"kind":"scienceScene","scene":"tree","seasons":["春","夏","秋","冬"],"caption":"春・夏・秋・冬の木のようす","study":true});

